# include <iostream># include <vector>struct points {	double x = 0;	double y = 0;	double z = 0;};int main() {	std::vector<points> triangle(3);	for (int i = 0; i < 3; ++i) {		std::cin >> triangle[i].x >> triangle[i].y >> triangle[i].z;	}	std::cout << "\nPoints\n";	for (int i = 0; i < triangle.size(); ++i) {		std::cout << triangle[i].x << triangle[i].y << triangle[i].z << std::endl;	}}